def chunk_into_n_parts(lst, n):
    if n == 0:
        return []
    chunk_size = len(lst) // n
    remainder = len(lst) % n
    result = []
    index = 0
    for i in range(n):
        if i < remainder:
            result.append(lst[index:index + chunk_size + 1])
        else:
            result.append(lst[index:index + chunk_size])
        index += chunk_size + 1
    return result
```

