def is_balanced_outside_quotes(s):
    stack = []
    in_quotes = False
    for c in s:
        if c == "'":
            in_quotes = not in_quotes
        elif c == '(' and not in_quotes:
            stack.append(c)
        elif c == ')' and not in_quotes:
            if not stack:
                return False
            stack.pop()
    return not stack
