def caesar_shift(s, shift):
    result = ''
    for c in s:
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            offset = ord(c) - base
            new_offset = (offset + shift) % 26
            result += chr(base + new_offset)
        else:
            result += c
    return result
```

